"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import { PdfPage } from "./pdf-viewer-page"
import { usePdfPageSizes } from "./pdf-viewer-page-sizes"
import { PdfViewerRail } from "./pdf-viewer-rail"
import {
  getDocumentResource,
  getPageResource,
  releaseDocumentResource,
  retainDocumentResource,
} from "./pdf-viewer-resource"
import { useMeasuredElementWidth, usePdfScale } from "./pdf-viewer-scale"
import { usePdfScroll } from "./pdf-viewer-scroll"
import {
  PageSkeleton,
  PdfErrorBoundary,
  PdfViewerFallback,
} from "./pdf-viewer-states"
import { PdfViewerToolbar } from "./pdf-viewer-toolbar"
import type {
  PageOverlayProps,
  PdfPageSize,
  PdfViewerHandle,
  PdfViewerSlots,
} from "./pdf-viewer-types"
import { usePdfPageVirtualization } from "./pdf-viewer-virtualization"

export { getDocumentResource, getPageResource } from "./pdf-viewer-resource"
export type {
  PageOverlayProps,
  PdfPageScrollTarget,
  PdfViewerHandle,
  PdfViewerSlots,
} from "./pdf-viewer-types"

function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export interface PdfHighlightProps extends React.ComponentProps<"div"> {
  /** Normalized box, each field a percentage [0, 100] of the page. */
  area: { left: number; top: number; width: number; height: number }
}

export function PdfHighlight({
  area,
  className,
  style,
  ...props
}: PdfHighlightProps) {
  return (
    <div
      data-slot="pdf-highlight"
      className={cn(
        "pointer-events-none absolute z-10 rounded-[2px] border border-primary/70 bg-primary/12 shadow-[0_4px_16px_rgb(0_0_0_/_8%)]",
        className
      )}
      style={{
        left: `${area.left}%`,
        top: `${area.top}%`,
        width: `${area.width}%`,
        height: `${area.height}%`,
        ...style,
      }}
      {...props}
    />
  )
}

export interface PdfViewerProps {
  /** URL of the PDF (same-origin or CORS-enabled). */
  src: string
  className?: string
  /** Controlled rendered scale; when omitted the viewer fits page width until manually zoomed. */
  scale?: number
  /** Initial uncontrolled scale. Leave unset for fit-to-width. */
  defaultScale?: number
  /** Called when toolbar controls request a scale change. `null` means fit width. */
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  downloadFileName?: string
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each page. */
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode
  /** Fired with the 1-based page nearest the top of the viewport as you scroll. */
  onVisiblePageChange?: (page: number) => void
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /**
   * Chrome mounted around the document. `top`/`bottom` are document-column
   * strips, `left`/`right` are rails, and `overlay` floats over the scroller.
   */
  slots?: PdfViewerSlots
  /** Show the toolbar button that collapses/expands rails. */
  railToggle?: boolean
  /** Initial open state of the rails. */
  defaultRailsOpen?: boolean
}

export const PdfViewer = React.forwardRef<PdfViewerHandle, PdfViewerProps>(
  function PdfViewer(props, ref) {
    const isClient = useIsClient()
    const hasRail = Boolean(props.slots?.left ?? props.slots?.right)
    const showRailToggle = Boolean(hasRail && (props.railToggle ?? true))

    if (!isClient) {
      return (
        <PdfViewerFallback
          className={props.className}
          bare={props.bare}
          toolbar={props.toolbar}
          showRailToggle={showRailToggle}
        />
      )
    }

    return (
      <PdfErrorBoundary className={props.className} resetKey={props.src}>
        <React.Suspense
          fallback={
            <PdfViewerFallback
              className={props.className}
              bare={props.bare}
              toolbar={props.toolbar}
              showRailToggle={showRailToggle}
            />
          }
        >
          <PdfViewerInner {...props} forwardedRef={ref} />
        </React.Suspense>
      </PdfErrorBoundary>
    )
  }
)

function PdfViewerInner({
  src,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  downloadFileName,
  renderPageOverlay,
  onVisiblePageChange,
  onScrollProgressChange,
  bare = false,
  slots,
  railToggle,
  defaultRailsOpen,
  forwardedRef,
}: PdfViewerProps & {
  forwardedRef?: React.ForwardedRef<PdfViewerHandle>
}) {
  const topSlot = slots?.top
  const bottomSlot = slots?.bottom
  const leftRailSlot = slots?.left
  const rightRailSlot = slots?.right
  const overlaySlot = slots?.overlay
  const showRailToggle = Boolean(
    (leftRailSlot || rightRailSlot) && (railToggle ?? true)
  )
  const [railsOpen, setRailsOpen] = React.useState(defaultRailsOpen ?? true)

  const document = React.use(getDocumentResource(src))
  React.useEffect(() => {
    retainDocumentResource(src, document)
    return () => releaseDocumentResource(src, document)
  }, [src, document])

  const firstPage = React.use(getPageResource(document, 1))
  const firstPageSize = React.useMemo<PdfPageSize>(() => {
    const viewport = firstPage.getViewport({ scale: 1 })
    return { width: viewport.width, height: viewport.height }
  }, [firstPage])

  const { ref: containerRef, width: containerWidth } = useMeasuredElementWidth()
  const { resolvedScale, zoomIn, zoomOut, fitWidth } = usePdfScale({
    controlledScale,
    defaultScale,
    onScaleChange,
    containerWidth,
    pageWidth: firstPageSize.width,
  })

  const [rotation, setRotation] = React.useState(0)
  const {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPageTarget,
    getViewportElement,
  } = usePdfScroll({
    pageCount: document.numPages,
    onVisiblePageChange,
    onScrollProgressChange,
  })
  const { visiblePages, registerPageSlot } = usePdfPageVirtualization({
    pageCount: document.numPages,
    viewportElement,
  })

  const { pageSizeByNumber, setPageSize } = usePdfPageSizes(document)

  const isRotated = rotation % 180 !== 0

  React.useEffect(() => {
    measureScroll()
  }, [
    document.numPages,
    measureScroll,
    rotation,
    resolvedScale,
    viewportElement,
  ])

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToPageTarget,
      getViewportElement,
    }),
    [getViewportElement, scrollToPageTarget]
  )

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="pdf-viewer"
    >
      {toolbar ? (
        <PdfViewerToolbar
          currentPage={currentPage}
          pageCount={document.numPages}
          scale={resolvedScale}
          src={src}
          downloadFileName={downloadFileName}
          showRailToggle={showRailToggle}
          railsOpen={railsOpen}
          onToggleRails={() => setRailsOpen((open) => !open)}
          onZoomOut={zoomOut}
          onZoomIn={zoomIn}
          onFitWidth={fitWidth}
          onRotate={() => setRotation((value) => (value + 90) % 360)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {leftRailSlot ? (
          <PdfViewerRail side="left" open={railsOpen} animate={showRailToggle}>
            {leftRailSlot}
          </PdfViewerRail>
        ) : null}
        <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
          {topSlot ? <div data-slot="pdf-viewer-top">{topSlot}</div> : null}
          <div className="relative flex min-h-0 flex-1 flex-col">
            <ScrollArea
              className="min-h-0 flex-1"
              viewportRef={setViewportElement}
              viewportProps={{ onScroll: handleScroll }}
            >
              <div
                ref={containerRef}
                className="flex flex-col items-center gap-4 p-4"
              >
                {Array.from({ length: document.numPages }, (_, index) => {
                  const pageNumber = index + 1
                  const pageSize = pageSizeByNumber.get(pageNumber) ?? {
                    width: firstPageSize.width,
                    height: firstPageSize.height,
                  }
                  const estimatedWidth = Math.round(
                    (isRotated ? pageSize.height : pageSize.width) *
                      resolvedScale
                  )
                  const estimatedHeight = Math.round(
                    (isRotated ? pageSize.width : pageSize.height) *
                      resolvedScale
                  )

                  return (
                    <div
                      key={pageNumber}
                      ref={registerPageSlot}
                      data-slot="pdf-page-slot"
                      data-page-number={pageNumber}
                      className="flex items-center justify-center"
                      style={{
                        width: estimatedWidth,
                        minHeight: estimatedHeight,
                      }}
                    >
                      {visiblePages.has(pageNumber) ? (
                        <React.Suspense fallback={<PageSkeleton />}>
                          <PdfPage
                            document={document}
                            pageNumber={pageNumber}
                            scale={resolvedScale}
                            rotation={rotation}
                            renderOverlay={renderPageOverlay}
                            onSize={setPageSize}
                          />
                        </React.Suspense>
                      ) : null}
                    </div>
                  )
                })}
              </div>
            </ScrollArea>
            {overlaySlot ? (
              <div
                data-slot="pdf-viewer-overlay"
                className="pointer-events-none absolute inset-0 z-10 [&>*]:pointer-events-auto"
              >
                {overlaySlot}
              </div>
            ) : null}
          </div>
          {bottomSlot ? (
            <div data-slot="pdf-viewer-bottom">{bottomSlot}</div>
          ) : null}
        </div>
        {rightRailSlot ? (
          <PdfViewerRail side="right" open={railsOpen} animate={showRailToggle}>
            {rightRailSlot}
          </PdfViewerRail>
        ) : null}
      </div>
    </div>
  )
}

import type * as React from "react"

export interface PageOverlayProps {
  pageNumber: number
  /** Rendered page size in CSS pixels (post-scale, post-rotation). */
  width: number
  height: number
  scale: number
  rotation: number
}

export type PdfPageScrollTarget = {
  top: number
}

export interface PdfViewerHandle {
  scrollToPageTarget: (
    pageNumber: number,
    target: PdfPageScrollTarget,
    options?: ScrollToOptions
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface PdfViewerSlots {
  /** Full-width strip directly below the toolbar (e.g. a legend). */
  top?: React.ReactNode
  /** Full-width strip at the bottom of the document column (e.g. a waterfall). */
  bottom?: React.ReactNode
  /** Collapsible rail to the left of the pages (e.g. a vertical page ribbon). */
  left?: React.ReactNode
  /** Collapsible rail to the right of the pages. */
  right?: React.ReactNode
  /** Absolutely-positioned layer over the scrolling pages (e.g. a floating legend). */
  overlay?: React.ReactNode
}

export type PdfPageSize = {
  width: number
  height: number
}

import type * as Pdfjs from "pdfjs-dist"
import type { PDFDocumentProxy, PDFPageProxy } from "pdfjs-dist"

const PDF_CACHE_MAX = 6

type DocumentCacheEntry = {
  promise: Promise<PDFDocumentProxy>
  consumers: number
  lastUsedAt: number
  status: "pending" | "fulfilled" | "rejected"
  document?: PDFDocumentProxy
}

let pdfjsPromise: Promise<typeof Pdfjs> | null = null
const documentCache = new Map<string, DocumentCacheEntry>()
const pageCache = new WeakMap<
  PDFDocumentProxy,
  Map<number, Promise<PDFPageProxy>>
>()
let pruneTimer = 0

function loadPdfjs() {
  if (!pdfjsPromise) {
    pdfjsPromise = import("pdfjs-dist").then((pdfjs) => {
      if (!pdfjs.GlobalWorkerOptions.workerSrc) {
        pdfjs.GlobalWorkerOptions.workerSrc = new URL(
          "pdfjs-dist/build/pdf.worker.min.mjs",
          import.meta.url
        ).toString()
      }
      return pdfjs
    })
  }
  return pdfjsPromise
}

function scheduleDocumentPrune() {
  if (typeof window === "undefined" || pruneTimer) return
  pruneTimer = window.setTimeout(() => {
    pruneTimer = 0
    pruneDocumentCache()
  }, 0)
}

function pruneDocumentCache() {
  while (documentCache.size > PDF_CACHE_MAX) {
    let evictKey: string | null = null
    let evictEntry: DocumentCacheEntry | null = null
    for (const [key, documentEntry] of documentCache) {
      if (documentEntry.consumers > 0 || documentEntry.status === "pending") {
        continue
      }
      if (!evictEntry || documentEntry.lastUsedAt < evictEntry.lastUsedAt) {
        evictKey = key
        evictEntry = documentEntry
      }
    }
    if (!evictKey || !evictEntry) return
    documentCache.delete(evictKey)
    if (evictEntry.status === "fulfilled") {
      void evictEntry.document?.destroy().catch(() => {})
    }
  }
}

export function getDocumentResource(src: string): Promise<PDFDocumentProxy> {
  const cachedDocumentEntry = documentCache.get(src)
  if (cachedDocumentEntry) {
    cachedDocumentEntry.lastUsedAt = Date.now()
    return cachedDocumentEntry.promise
  }

  const documentEntry: DocumentCacheEntry = {
    promise: Promise.resolve(null as never),
    consumers: 0,
    lastUsedAt: Date.now(),
    status: "pending",
  }
  documentEntry.promise = loadPdfjs()
    .then((pdfjs) => pdfjs.getDocument(src).promise)
    .then(
      (document) => {
        documentEntry.status = "fulfilled"
        documentEntry.document = document
        scheduleDocumentPrune()
        return document
      },
      (error) => {
        documentEntry.status = "rejected"
        if (documentCache.get(src) === documentEntry) documentCache.delete(src)
        throw error
      }
    )

  documentCache.set(src, documentEntry)
  scheduleDocumentPrune()
  return documentEntry.promise
}

export function retainDocumentResource(
  src: string,
  document: PDFDocumentProxy
) {
  const documentEntry = documentCache.get(src)
  if (!documentEntry || documentEntry.document !== document) return
  documentEntry.consumers += 1
  documentEntry.lastUsedAt = Date.now()
}

export function releaseDocumentResource(
  src: string,
  document: PDFDocumentProxy
) {
  const documentEntry = documentCache.get(src)
  if (!documentEntry || documentEntry.document !== document) return
  documentEntry.consumers = Math.max(0, documentEntry.consumers - 1)
  documentEntry.lastUsedAt = Date.now()
  scheduleDocumentPrune()
}

export function __resetPdfDocumentCacheForTests() {
  if (pruneTimer && typeof window !== "undefined") {
    window.clearTimeout(pruneTimer)
    pruneTimer = 0
  }
  for (const documentEntry of documentCache.values()) {
    if (documentEntry.status === "fulfilled") {
      void documentEntry.document?.destroy().catch(() => {})
    }
  }
  documentCache.clear()
}

export function getPageResource(
  document: PDFDocumentProxy,
  pageNumber: number
) {
  let pages = pageCache.get(document)
  if (!pages) {
    pages = new Map()
    pageCache.set(document, pages)
  }
  let pagePromise = pages.get(pageNumber)
  if (!pagePromise) {
    pagePromise = document.getPage(pageNumber)
    pages.set(pageNumber, pagePromise)
  }
  return pagePromise
}

import * as React from "react"

export const MIN_PDF_SCALE = 0.25
export const MAX_PDF_SCALE = 5
export const PDF_ZOOM_STEP = 1.2
export const PDF_PAGE_HORIZONTAL_PADDING = 32

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function clampPdfScale(value: number) {
  return clamp(Number.isFinite(value) ? value : 1, MIN_PDF_SCALE, MAX_PDF_SCALE)
}

export function getPdfFitWidthScale(
  containerWidth: number | null,
  pageWidth: number
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || pageWidth <= 0) {
    return 1
  }
  return clampPdfScale(
    (containerWidth - PDF_PAGE_HORIZONTAL_PADDING) / pageWidth
  )
}

export function useMeasuredElementWidth() {
  const [width, setWidth] = React.useState<number | null>(null)

  const ref = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setWidth(element.clientWidth)
    if (typeof ResizeObserver === "undefined") return

    let frame = 0
    let latestWidth = element.clientWidth
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        latestWidth = (entry.target as HTMLElement).clientWidth
      }
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        setWidth(latestWidth)
      })
    })

    observer.observe(element)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  return { ref, width }
}

export function usePdfScale({
  controlledScale,
  defaultScale,
  onScaleChange,
  containerWidth,
  pageWidth,
}: {
  controlledScale?: number
  defaultScale?: number
  onScaleChange?: (scale: number | null) => void
  containerWidth: number | null
  pageWidth: number
}) {
  const [uncontrolledRequestedScale, setUncontrolledRequestedScale] =
    React.useState<number | null>(() =>
      defaultScale == null ? null : clampPdfScale(defaultScale)
    )
  const isControlledScale = controlledScale !== undefined
  const fitWidthScale = getPdfFitWidthScale(containerWidth, pageWidth)
  const resolvedScale = isControlledScale
    ? clampPdfScale(controlledScale)
    : (uncontrolledRequestedScale ?? fitWidthScale)

  const setRequestedScale = React.useCallback(
    (nextScale: number | null) => {
      const normalizedScale =
        nextScale == null ? null : clampPdfScale(nextScale)
      if (isControlledScale) {
        onScaleChange?.(normalizedScale)
        return
      }
      setUncontrolledRequestedScale(normalizedScale)
    },
    [isControlledScale, onScaleChange]
  )

  const zoomIn = React.useCallback(
    () => setRequestedScale(resolvedScale * PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale]
  )
  const zoomOut = React.useCallback(
    () => setRequestedScale(resolvedScale / PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale]
  )
  const fitWidth = React.useCallback(
    () => setRequestedScale(null),
    [setRequestedScale]
  )

  return {
    resolvedScale,
    zoomIn,
    zoomOut,
    fitWidth,
  }
}

import * as React from "react"

import { clamp } from "./pdf-viewer-scale"
import type { PdfPageScrollTarget } from "./pdf-viewer-types"

const PDF_SCROLL_TARGET_HEADROOM = 48

export function usePdfScroll({
  pageCount,
  onVisiblePageChange,
  onScrollProgressChange,
}: {
  pageCount: number
  onVisiblePageChange?: (page: number) => void
  onScrollProgressChange?: (progress: number) => void
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const lastReportedPageRef = React.useRef(0)
  const scrollFrameRef = React.useRef(0)
  const [viewportElement, setViewportElementState] =
    React.useState<HTMLDivElement | null>(null)
  const [currentPage, setCurrentPage] = React.useState(1)

  const setViewportElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element
      setViewportElementState(element)
    },
    []
  )

  const measureScroll = React.useCallback(() => {
    scrollFrameRef.current = 0
    const viewportElement = viewportElementRef.current
    if (!viewportElement) return

    const scrollable =
      viewportElement.scrollHeight - viewportElement.clientHeight
    const progress =
      scrollable > 0 ? clamp(viewportElement.scrollTop / scrollable, 0, 1) : 0
    onScrollProgressChange?.(progress)

    const viewportRect = viewportElement.getBoundingClientRect()
    const marker = viewportRect.top + viewportRect.height * 0.2
    const pageSlots =
      viewportElement.querySelectorAll<HTMLElement>("[data-page-number]")
    let visiblePage = 1
    for (const pageSlot of pageSlots) {
      if (pageSlot.getBoundingClientRect().top <= marker) {
        visiblePage = Number(pageSlot.dataset.pageNumber)
      } else {
        break
      }
    }

    if (
      visiblePage >= 1 &&
      visiblePage <= pageCount &&
      visiblePage !== lastReportedPageRef.current
    ) {
      lastReportedPageRef.current = visiblePage
      setCurrentPage(visiblePage)
      onVisiblePageChange?.(visiblePage)
    }
  }, [onScrollProgressChange, onVisiblePageChange, pageCount])

  const handleScroll = React.useCallback(() => {
    if (scrollFrameRef.current) return
    scrollFrameRef.current = requestAnimationFrame(measureScroll)
  }, [measureScroll])

  const scrollToPageTarget = React.useCallback(
    (
      pageNumber: number,
      target: PdfPageScrollTarget,
      options?: ScrollToOptions
    ) => {
      const viewportElement = viewportElementRef.current
      if (!viewportElement || pageNumber < 1 || pageNumber > pageCount) return

      const pageSlot = viewportElement.querySelector<HTMLElement>(
        `[data-page-number="${pageNumber}"]`
      )
      if (!pageSlot) return

      const pageSlotRect = pageSlot.getBoundingClientRect()
      const viewportRect = viewportElement.getBoundingClientRect()
      const pageTop =
        pageSlotRect.top - viewportRect.top + viewportElement.scrollTop
      const targetTopPercent = clamp(target.top, 0, 100)
      const targetTop =
        pageTop +
        (targetTopPercent / 100) * pageSlotRect.height -
        PDF_SCROLL_TARGET_HEADROOM

      viewportElement.scrollTo({
        top: Math.max(0, targetTop),
        behavior: "smooth",
        ...options,
      })
    },
    [pageCount]
  )
  const getViewportElement = React.useCallback(
    () => viewportElementRef.current,
    []
  )

  React.useEffect(
    () => () => {
      if (scrollFrameRef.current) cancelAnimationFrame(scrollFrameRef.current)
    },
    []
  )

  return {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPageTarget,
    getViewportElement,
  }
}

import * as React from "react"

export function usePdfPageVirtualization({
  pageCount,
  viewportElement,
}: {
  pageCount: number
  viewportElement: HTMLDivElement | null
}) {
  const [visiblePages, setVisiblePages] = React.useState<ReadonlySet<number>>(
    () => new Set([1])
  )
  const observerRef = React.useRef<IntersectionObserver | null>(null)
  const slotElementsRef = React.useRef<Set<HTMLElement>>(new Set())

  React.useEffect(() => {
    setVisiblePages(new Set([1]))
  }, [pageCount])

  React.useEffect(() => {
    if (!viewportElement) return
    if (typeof IntersectionObserver === "undefined") {
      setVisiblePages(
        new Set(Array.from({ length: pageCount }, (_, index) => index + 1))
      )
      return
    }

    const observer = new IntersectionObserver(
      (entries) => {
        setVisiblePages((previousVisiblePages) => {
          const nextVisiblePages = new Set(previousVisiblePages)
          let changed = false
          for (const entry of entries) {
            const pageNumber = Number(
              (entry.target as HTMLElement).dataset.pageNumber
            )
            if (!pageNumber) continue
            if (entry.isIntersecting) {
              if (!nextVisiblePages.has(pageNumber)) {
                nextVisiblePages.add(pageNumber)
                changed = true
              }
            } else if (nextVisiblePages.delete(pageNumber)) {
              changed = true
            }
          }
          return changed ? nextVisiblePages : previousVisiblePages
        })
      },
      { root: viewportElement, rootMargin: "100% 0px" }
    )

    observerRef.current = observer
    for (const slotElement of slotElementsRef.current) {
      observer.observe(slotElement)
    }

    return () => {
      observer.disconnect()
      observerRef.current = null
    }
  }, [pageCount, viewportElement])

  const registerPageSlot = React.useCallback((element: HTMLElement | null) => {
    if (!element) return
    slotElementsRef.current.add(element)
    observerRef.current?.observe(element)
    return () => {
      slotElementsRef.current.delete(element)
      observerRef.current?.unobserve(element)
    }
  }, [])

  return { visiblePages, registerPageSlot }
}

import * as React from "react"

import type { PdfPageSize } from "./pdf-viewer-types"

export function usePdfPageSizes(resetKey: unknown) {
  const [pageSizeByNumber, setPageSizeByNumber] = React.useState<
    ReadonlyMap<number, PdfPageSize>
  >(() => new Map())

  React.useEffect(() => setPageSizeByNumber(new Map()), [resetKey])

  const setPageSize = React.useCallback(
    (pageNumber: number, size: PdfPageSize) => {
      setPageSizeByNumber((previousPageSizeByNumber) => {
        const current = previousPageSizeByNumber.get(pageNumber)
        if (current?.width === size.width && current.height === size.height) {
          return previousPageSizeByNumber
        }
        const nextPageSizeByNumber = new Map(previousPageSizeByNumber)
        nextPageSizeByNumber.set(pageNumber, size)
        return nextPageSizeByNumber
      })
    },
    []
  )

  return { pageSizeByNumber, setPageSize }
}

import * as React from "react"
import type { PDFDocumentProxy } from "pdfjs-dist"

import { getPageResource } from "./pdf-viewer-resource"
import type { PageOverlayProps, PdfPageSize } from "./pdf-viewer-types"

export function PdfPage({
  document,
  pageNumber,
  scale,
  rotation,
  renderOverlay,
  onSize,
}: {
  document: PDFDocumentProxy
  pageNumber: number
  scale: number
  rotation: number
  renderOverlay?: (props: PageOverlayProps) => React.ReactNode
  onSize?: (pageNumber: number, size: PdfPageSize) => void
}) {
  const page = React.use(getPageResource(document, pageNumber))
  const intrinsicViewport = React.useMemo(
    () => page.getViewport({ scale: 1, rotation: page.rotate ?? 0 }),
    [page]
  )

  React.useEffect(() => {
    onSize?.(pageNumber, {
      width: intrinsicViewport.width,
      height: intrinsicViewport.height,
    })
  }, [intrinsicViewport.height, intrinsicViewport.width, onSize, pageNumber])

  const viewport = React.useMemo(
    () =>
      page.getViewport({
        scale,
        rotation: ((page.rotate ?? 0) + rotation) % 360,
      }),
    [page, rotation, scale]
  )
  const devicePixelRatio =
    (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return
      const context = canvas.getContext("2d")
      if (!context) return

      canvas.width = Math.floor(viewport.width * devicePixelRatio)
      canvas.height = Math.floor(viewport.height * devicePixelRatio)
      const renderTask = page.render({
        canvas,
        canvasContext: context,
        viewport,
        transform:
          devicePixelRatio !== 1
            ? [devicePixelRatio, 0, 0, devicePixelRatio, 0, 0]
            : undefined,
      })
      renderTask.promise.catch(() => {
        /* cancelled or failed render */
      })
      return () => renderTask.cancel()
    },
    [devicePixelRatio, page, viewport]
  )

  return (
    <div
      className="relative shadow-sm ring-1 ring-border"
      style={{ width: viewport.width, height: viewport.height }}
      data-slot="pdf-page"
      data-page={pageNumber}
    >
      <canvas
        ref={canvasRef}
        style={{ width: viewport.width, height: viewport.height }}
        className="block bg-white"
      />
      {renderOverlay ? (
        <div className="pointer-events-none absolute inset-0">
          {renderOverlay({
            pageNumber,
            width: viewport.width,
            height: viewport.height,
            scale,
            rotation,
          })}
        </div>
      ) : null}
    </div>
  )
}

import * as React from "react"

import { cn } from "@/lib/utils"

export function PdfViewerRail({
  side,
  open,
  animate,
  children,
}: {
  side: "left" | "right"
  open: boolean
  animate: boolean
  children: React.ReactNode
}) {
  const [width, setWidth] = React.useState<number | null>(null)
  const measureRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setWidth(Math.round(element.offsetWidth))
    if (typeof ResizeObserver === "undefined") return

    const observer = new ResizeObserver(() =>
      setWidth(Math.round(element.offsetWidth))
    )
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  return (
    <div
      data-slot="pdf-viewer-rail"
      data-side={side}
      data-state={open ? "open" : "closed"}
      className={cn(
        "h-full flex-shrink-0 overflow-hidden",
        animate && "transition-[width] duration-200 ease-out"
      )}
      style={animate ? { width: open ? (width ?? undefined) : 0 } : undefined}
    >
      <div ref={measureRef} className="h-full w-max">
        {children}
      </div>
    </div>
  )
}

